{"query":"
	query GetSeriesChains($ids: [Int]) {
		Page(perPage: 50) {
			media(id_in: $ids, type: ANIME) {
				id episodes format status
				relations { edges { relationType node {
					id episodes format status
					relations { edges { relationType node {
						id episodes format status
					} } }
				} } }
			}
		}
	}
","variables":{"ids":[1]}}
